//! The compiler/std/standard matrix: cpp-anything's knowledge base.
//!
//! `data/matrix.json` is generated by `scripts/sync_matrix.py` from cppreference's
//! compiler support tables and embedded in the binary, so `matrix` answers the same
//! way on a machine with no network, no checkout and no C++ toolchain. The guides
//! in `docs/guides/` are rendered from the same data by `matrix docs`, and
//! `matrix check` fails when they drift.

use std::collections::BTreeMap;
use std::sync::LazyLock;

use crate::json::Json;
use crate::util::{version_at_least, version_key};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Status {
    Yes,
    Partial,
    No,
}

impl Status {
    pub fn label(self) -> &'static str {
        match self {
            Status::Yes => "yes",
            Status::Partial => "partial",
            Status::No => "no",
        }
    }

    pub fn usable(self) -> bool {
        matches!(self, Status::Yes)
    }
}

#[derive(Clone, Debug)]
pub struct Support {
    pub status: Status,
    pub min: Option<String>,
    pub notes: Vec<String>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Kind {
    Core,
    Library,
}

impl Kind {
    pub fn label(self) -> &'static str {
        match self {
            Kind::Core => "core",
            Kind::Library => "library",
        }
    }
}

#[derive(Clone, Debug)]
pub struct Feature {
    pub id: String,
    pub name: String,
    pub kind: Kind,
    pub std: String,
    pub macro_id: String,
    pub paper: String,
    pub support: Vec<(String, Support)>,
}

impl Feature {
    pub fn toolchain(&self, toolchain: &str) -> Option<&Support> {
        self.support
            .iter()
            .find(|(name, _)| name == toolchain)
            .map(|(_, support)| support)
    }

    /// The release that first implements the feature completely, if recorded.
    pub fn first_release(&self, toolchain: &str) -> Option<&str> {
        let support = self.toolchain(toolchain)?;
        if support.status.usable() {
            support.min.as_deref()
        } else {
            None
        }
    }

    pub fn std_number(&self) -> u32 {
        self.std.trim_start_matches("c++").parse().unwrap_or(0)
    }
}

#[derive(Clone, Debug)]
pub struct Source {
    pub title: String,
    pub url: String,
    pub revision: Option<String>,
    pub timestamp: Option<String>,
}

pub struct Matrix {
    pub generated_at: String,
    pub features: Vec<Feature>,
    pub toolchains: Vec<(String, String)>,
    pub sources: Vec<Source>,
    pub standards: Vec<String>,
    pub msvc_titles: BTreeMap<String, String>,
    pub license: String,
}

const RAW: &str = include_str!("../data/matrix.json");

static MATRIX: LazyLock<Matrix> = LazyLock::new(|| {
    Matrix::parse(RAW).unwrap_or_else(|error| {
        panic!(
            "embedded data/matrix.json is not readable ({error}); \
             regenerate it with scripts/sync_matrix.py"
        )
    })
});

impl Matrix {
    pub fn get() -> &'static Matrix {
        &MATRIX
    }

    fn parse(raw: &str) -> Result<Matrix, String> {
        let doc = Json::parse(raw)?;
        let mut features = Vec::new();
        for item in doc
            .get("features")
            .and_then(Json::as_array)
            .ok_or("missing features")?
        {
            let mut support = Vec::new();
            if let Some(entries) = item.get("support").and_then(Json::as_object) {
                for (toolchain, value) in entries {
                    let status = match value.get("status").and_then(Json::as_str) {
                        Some("yes") => Status::Yes,
                        Some("partial") => Status::Partial,
                        _ => Status::No,
                    };
                    support.push((
                        toolchain.clone(),
                        Support {
                            status,
                            min: value.get("min").and_then(Json::as_str).map(str::to_string),
                            notes: value
                                .get("notes")
                                .and_then(Json::as_array)
                                .map(|notes| {
                                    notes
                                        .iter()
                                        .filter_map(|note| note.as_str().map(str::to_string))
                                        .collect()
                                })
                                .unwrap_or_default(),
                        },
                    ));
                }
            }
            features.push(Feature {
                id: string_field(item, "id"),
                name: string_field(item, "name"),
                kind: if string_field(item, "kind") == "library" {
                    Kind::Library
                } else {
                    Kind::Core
                },
                std: string_field(item, "std"),
                macro_id: string_field(item, "macro"),
                paper: string_field(item, "paper"),
                support,
            });
        }

        let toolchains = doc
            .get("toolchains")
            .and_then(Json::as_object)
            .map(|entries| {
                entries
                    .iter()
                    .map(|(id, value)| {
                        (
                            id.clone(),
                            value
                                .get("label")
                                .and_then(Json::as_str)
                                .unwrap_or(id)
                                .to_string(),
                        )
                    })
                    .collect()
            })
            .unwrap_or_default();

        let mut sources = Vec::new();
        for item in doc
            .get("sources")
            .and_then(Json::as_array)
            .unwrap_or_default()
        {
            sources.push(Source {
                title: string_field(item, "title"),
                url: string_field(item, "url"),
                revision: item
                    .get("revid")
                    .and_then(Json::as_i64)
                    .map(|id| id.to_string()),
                timestamp: item
                    .get("rev_timestamp")
                    .and_then(Json::as_str)
                    .map(str::to_string),
            });
        }

        let standards = doc
            .get("standards")
            .and_then(Json::as_array)
            .map(|items| {
                items
                    .iter()
                    .filter_map(|item| item.get("std").and_then(Json::as_str).map(str::to_string))
                    .collect()
            })
            .unwrap_or_else(|| vec!["c++17".into(), "c++20".into(), "c++23".into()]);

        let mut msvc_titles = BTreeMap::new();
        if let Some(titles) = doc
            .get("msvc_versions")
            .and_then(|value| value.get("titles"))
            .and_then(Json::as_object)
        {
            for (version, title) in titles {
                if let Some(text) = title.as_str() {
                    msvc_titles.insert(version.clone(), text.to_string());
                }
            }
        }

        let license = doc
            .get("source_license")
            .map(|value| {
                format!(
                    "{} ({})",
                    value
                        .get("title")
                        .and_then(Json::as_str)
                        .unwrap_or("cppreference"),
                    value
                        .get("license")
                        .and_then(Json::as_str)
                        .unwrap_or("CC-BY-SA")
                )
            })
            .unwrap_or_else(|| "cppreference.com".to_string());

        Ok(Matrix {
            generated_at: string_field(&doc, "generated_at"),
            features,
            toolchains,
            sources,
            standards,
            msvc_titles,
            license,
        })
    }

    pub fn toolchain_label(&self, id: &str) -> String {
        self.toolchains
            .iter()
            .find(|(name, _)| name == id)
            .map(|(_, label)| label.clone())
            .unwrap_or_else(|| id.to_string())
    }

    /// Canonical toolchain id for a CLI alias (`g++`, `clang++`, `msvc`, `libc++`).
    pub fn resolve_toolchain(&self, name: &str) -> Option<String> {
        let normalized = name.trim().to_ascii_lowercase().replace('_', "-");
        let alias = match normalized.as_str() {
            "g++" | "gcc" | "gnu" | "libstdc++" | "gcc-libstdc++" => "gcc",
            "clang" | "clang++" | "llvm" | "libc++" | "clang-libc++" => "clang",
            "msvc" | "msvc-stl" | "cl" | "visual-c++" | "vs" => "msvc",
            "apple-clang" | "appleclang" | "xcode" => "aclang",
            other => other,
        };
        if self.toolchains.iter().any(|(id, _)| id == alias) {
            Some(alias.to_string())
        } else {
            None
        }
    }

    pub fn features_in(&self, std: &str) -> Vec<&Feature> {
        let mut features: Vec<&Feature> = self
            .features
            .iter()
            .filter(|feature| feature.std == std)
            .collect();
        features.sort_by(|a, b| (a.kind.label(), &a.name).cmp(&(b.kind.label(), &b.name)));
        features
    }

    /// What a given compiler release supports of one standard.
    pub fn audit(&self, toolchain: &str, version: &str, std: &str) -> Audit<'_> {
        let mut supported = Vec::new();
        let mut missing = Vec::new();
        let mut partial = Vec::new();
        for feature in self.features_in(std) {
            match feature.toolchain(toolchain) {
                Some(support) if support.status == Status::Yes => {
                    if support
                        .min
                        .as_deref()
                        .is_none_or(|min| version_at_least(version, min))
                    {
                        supported.push(feature);
                    } else {
                        missing.push(feature);
                    }
                }
                Some(support) if support.status == Status::Partial => partial.push(feature),
                _ => missing.push(feature),
            }
        }
        Audit {
            supported,
            partial,
            missing,
        }
    }

    /// First release of `toolchain` that implements every core feature of `std`.
    pub fn first_complete_core(&self, toolchain: &str, std: &str) -> Option<String> {
        self.first_complete(toolchain, std, Kind::Core)
    }

    pub fn first_complete_library(&self, toolchain: &str, std: &str) -> Option<String> {
        self.first_complete(toolchain, std, Kind::Library)
    }

    fn first_complete(&self, toolchain: &str, std: &str, kind: Kind) -> Option<String> {
        let features: Vec<&Feature> = self
            .features_in(std)
            .into_iter()
            .filter(|feature| feature.kind == kind)
            .collect();
        if features.is_empty() {
            return None;
        }
        let mut highest: Option<String> = None;
        for feature in features {
            let support = feature.toolchain(toolchain)?;
            match support.status {
                Status::Yes => {}
                // A partial feature still ships; the compiler guide lists it under
                // "still partial" instead of hiding the release that is complete
                // apart from it.
                Status::Partial => continue,
                Status::No => return None,
            }
            // cppreference sometimes records "yes" without a release. Treating it
            // as satisfied is the only reading that does not make the whole table
            // unknown; the guides say so.
            if let Some(min) = &support.min {
                if highest
                    .as_deref()
                    .is_none_or(|best| version_key(min) > version_key(best))
                {
                    highest = Some(min.clone());
                }
            }
        }
        highest.or_else(|| Some("any".to_string()))
    }

    /// Number of features of a standard that a release implements.
    pub fn supported_counts(
        &self,
        toolchain: &str,
        version: &str,
        std: &str,
    ) -> (usize, usize, usize) {
        let audit = self.audit(toolchain, version, std);
        (
            audit.supported.len(),
            audit.partial.len(),
            audit.missing.len(),
        )
    }

    /// Lookup by feature-test macro (`__cpp_lib_expected`), by id, or by name.
    pub fn lookup(&self, query: &str) -> Vec<&Feature> {
        let needle = query.trim();
        if needle.is_empty() {
            return Vec::new();
        }
        let lowered = needle.to_ascii_lowercase();
        let mut exact: Vec<&Feature> = Vec::new();
        let mut partial: Vec<&Feature> = Vec::new();
        for feature in &self.features {
            let macro_name = feature.macro_id.split_whitespace().next().unwrap_or("");
            if feature.id == needle || macro_name == needle {
                exact.push(feature);
            } else if feature.name.to_ascii_lowercase().contains(&lowered)
                || feature.id.to_ascii_lowercase().contains(&lowered)
                || macro_name.contains(needle)
            {
                partial.push(feature);
            }
        }
        exact.extend(partial);
        exact
    }

    /// The earliest feature row that defines a feature-test macro, which is the one
    /// that says when the facility first appeared.
    pub fn by_macro(&self, macro_name: &str) -> Option<&Feature> {
        self.features
            .iter()
            .filter(|feature| {
                feature.macro_id.split_whitespace().next().unwrap_or("") == macro_name
            })
            .min_by_key(|feature| feature.std_number())
    }

    /// Availability of a macro in `std` for a toolchain release.
    pub fn macro_available(
        &self,
        macro_name: &str,
        toolchain: &str,
        version: &str,
        std: &str,
    ) -> MacroStatus {
        let Some(feature) = self.by_macro(macro_name) else {
            return MacroStatus::Unknown;
        };
        let limit = std.trim_start_matches("c++").parse::<u32>().unwrap_or(0);
        if feature.std_number() > limit {
            return MacroStatus::TooNew(feature.std.clone(), feature.name.clone());
        }
        match feature.toolchain(toolchain) {
            Some(support) if support.status == Status::Yes => match support.min.as_deref() {
                Some(min) if version_at_least(version, min) => {
                    MacroStatus::Available(min.to_string(), feature.name.clone())
                }
                Some(min) => MacroStatus::TooOld(min.to_string(), feature.name.clone()),
                None => MacroStatus::Available("?".into(), feature.name.clone()),
            },
            Some(support) if support.status == Status::Partial => MacroStatus::Partial(
                support.min.clone().unwrap_or_else(|| "?".into()),
                feature.name.clone(),
            ),
            _ => MacroStatus::Missing(feature.name.clone()),
        }
    }
}

fn string_field(item: &Json, key: &str) -> String {
    item.get(key)
        .and_then(Json::as_str)
        .unwrap_or_default()
        .to_string()
}

#[derive(Clone, Debug)]
pub enum MacroStatus {
    Available(String, String),
    TooOld(String, String),
    Partial(String, String),
    TooNew(String, String),
    Missing(String),
    Unknown,
}

impl MacroStatus {
    pub fn available(&self) -> bool {
        matches!(self, MacroStatus::Available(_, _))
    }
}

#[derive(Clone, Debug)]
pub struct Audit<'a> {
    pub supported: Vec<&'a Feature>,
    pub partial: Vec<&'a Feature>,
    pub missing: Vec<&'a Feature>,
}

/// The features cpp-anything's own generated code can use, keyed by the macro it
/// defines in `profile.hpp`. Every entry names the feature-test macro it depends
/// on, so availability comes from the matrix and never from a compiler guess.
pub const PROFILE_FEATURES: &[(&str, &str)] = &[
    ("CPPAN_HAS_CONCEPTS", "__cpp_concepts"),
    ("CPPAN_HAS_COROUTINES", "__cpp_impl_coroutine"),
    ("CPPAN_HAS_SPAN", "__cpp_lib_span"),
    ("CPPAN_HAS_RANGES", "__cpp_lib_ranges"),
    ("CPPAN_HAS_RANGES_TO", "__cpp_lib_ranges_to_container"),
    ("CPPAN_HAS_FORMAT", "__cpp_lib_format"),
    ("CPPAN_HAS_PRINT", "__cpp_lib_print"),
    ("CPPAN_HAS_EXPECTED", "__cpp_lib_expected"),
    ("CPPAN_HAS_MDSPAN", "__cpp_lib_mdspan"),
    ("CPPAN_HAS_STACKTRACE", "__cpp_lib_stacktrace"),
    ("CPPAN_HAS_FLAT_MAP", "__cpp_lib_flat_map"),
    ("CPPAN_HAS_GENERATOR", "__cpp_lib_generator"),
    ("CPPAN_HAS_THREE_WAY", "__cpp_impl_three_way_comparison"),
    ("CPPAN_HAS_DEDUCING_THIS", "__cpp_explicit_this_parameter"),
    ("CPPAN_HAS_MODULES", "__cpp_modules"),
    ("CPPAN_HAS_LIB_MODULES", "__cpp_lib_modules"),
    ("CPPAN_HAS_SOURCE_LOCATION", "__cpp_lib_source_location"),
    ("CPPAN_HAS_BIT_CAST", "__cpp_lib_bit_cast"),
    ("CPPAN_HAS_TO_CHARS_FLOAT", "__cpp_lib_to_chars"),
];

/// `profile.hpp`: the header every generated project includes, claiming exactly
/// what the target toolchain has.
pub fn render_profile(toolchain: &str, version: &str, std: &str) -> String {
    let matrix = Matrix::get();
    let mut out = String::new();
    out.push_str("// Generated by `cpp-anything matrix profile`; do not edit.\n");
    out.push_str("//\n");
    out.push_str("// Claims about the target toolchain come from data/matrix.json, which is\n");
    out.push_str("// synced from cppreference's compiler support tables. Regenerate with:\n");
    out.push_str("//   cpp-anything matrix profile --toolchain ");
    out.push_str(toolchain);
    out.push_str(" --version ");
    out.push_str(version);
    out.push_str(" --std ");
    out.push_str(std);
    out.push_str("\n#pragma once\n\n");
    out.push_str(&format!("#define CPPAN_TOOLCHAIN \"{toolchain}\"\n"));
    out.push_str(&format!("#define CPPAN_TOOLCHAIN_VERSION \"{version}\"\n"));
    let std_number = std.trim_start_matches("c++");
    out.push_str(&format!("#define CPPAN_CXX_STANDARD {std_number}\n"));
    out.push_str(&format!(
        "#define CPPAN_MATRIX_GENERATED_AT \"{}\"\n\n",
        matrix.generated_at
    ));
    for (name, macro_name) in PROFILE_FEATURES {
        let status = matrix.macro_available(macro_name, toolchain, version, std);
        let value = if status.available() { 1 } else { 0 };
        let comment = match &status {
            MacroStatus::Available(min, feature) => format!("{feature} since {min}"),
            MacroStatus::TooOld(min, feature) => format!("{feature} needs {min}"),
            MacroStatus::Partial(min, feature) => format!("{feature} partial since {min}"),
            MacroStatus::TooNew(need, feature) => format!("{feature} arrives in {need}"),
            MacroStatus::Missing(feature) => format!("{feature}: not implemented"),
            MacroStatus::Unknown => "no matrix entry".to_string(),
        };
        out.push_str(&format!(
            "#define {name} {value}  // {comment} ({macro_name})\n"
        ));
    }
    out.push_str(&format!(
        "\nstatic_assert(__cplusplus >= {}L,\n              \"cpp-anything needs {std} for this project; see docs/guides/compilers/{} if your compiler disagrees\");\n",
        std_macro(std),
        toolchain
    ));
    out.push_str(
        "\n// std::expected on C++23 targets; cppan::Result (same shape) where the library\n// does not have it yet. The port says cppan::Result<T> either way.\n",
    );
    out
}

pub fn std_macro(std: &str) -> &'static str {
    match std.trim_start_matches("c++") {
        "11" => "201103",
        "14" => "201402",
        "17" => "201703",
        "20" => "202002",
        _ => "202302",
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn embedded_matrix_parses() {
        let matrix = Matrix::get();
        assert!(
            matrix.features.len() > 500,
            "features: {}",
            matrix.features.len()
        );
        assert!(matrix.standards.contains(&"c++23".to_string()));
        assert!(!matrix.sources.is_empty());
    }

    #[test]
    fn knows_expected_needs_a_modern_compiler() {
        let matrix = Matrix::get();
        assert!(matrix
            .macro_available("__cpp_lib_expected", "gcc", "12", "c++23")
            .available());
        assert!(!matrix
            .macro_available("__cpp_lib_expected", "gcc", "11", "c++23")
            .available());
        assert!(!matrix
            .macro_available("__cpp_lib_expected", "gcc", "15", "c++20")
            .available());
    }

    #[test]
    fn resolves_toolchain_aliases() {
        let matrix = Matrix::get();
        assert_eq!(matrix.resolve_toolchain("g++").as_deref(), Some("gcc"));
        assert_eq!(
            matrix.resolve_toolchain("clang++").as_deref(),
            Some("clang")
        );
        assert_eq!(matrix.resolve_toolchain("msvc").as_deref(), Some("msvc"));
        assert!(matrix.resolve_toolchain("watcom").is_none());
    }

    #[test]
    fn profile_reports_the_target() {
        // GCC 12 shipped <expected>; GCC 11 did not, and C++20 never has it.
        assert!(render_profile("gcc", "13", "c++23").contains("#define CPPAN_HAS_EXPECTED 1"));
        assert!(render_profile("gcc", "11", "c++23").contains("#define CPPAN_HAS_EXPECTED 0"));
        assert!(render_profile("gcc", "13", "c++20").contains("#define CPPAN_HAS_EXPECTED 0"));
        let profile = render_profile("gcc", "13", "c++23");
        assert!(profile.contains("CPPAN_CXX_STANDARD 23"));
        assert!(
            profile.contains("CPPAN_HAS_PRINT 0"),
            "std::print is C++23 and GCC 13 lacks it"
        );
        assert!(render_profile("gcc", "15", "c++23").contains("CPPAN_HAS_PRINT 1"));
    }
}
